import json,pathlib
p=pathlib.Path(__file__).resolve().parents[2]/'data';content=json.loads((p/'content.json').read_text(encoding='utf8'))
items=[
('address','搭配','The committee promised to address the problem at its next meeting.','Which expression has the same grammatical pattern as “address the problem”?',['address the concern','address to the concern','address on the concern','address about the concern'],0,['address 作“处理”时直接接宾语，可说 address the concern。','此义为及物用法，不加 to。','此义不加 on。','此义不加 about。']),
('access','搭配','The pass gives researchers access to the manuscript room.','Which phrase correctly completes “access ___ the manuscript room”?',['to','at','for','with'],0,['表示“使用某物的机会或权利”时常用 access to。','access at 不能表达这里的关系。','access for 不能在这里直接接所使用的房间。','access with 不构成本句所需搭配。']),
('patient','多义词','The patient guide waited calmly while the group found the right path.','What does “patient” describe here?',['a calm attitude while waiting','a person receiving treatment','a place for medical care','a sudden feeling of anger'],0,['patient 在这里是形容词，修饰 guide，表示有耐心。','patient 可作“病人”的名词，但本句并非该用法。','医院或诊所是场所，不是 patient 的意思。','patient 表示耐心，和突然生气不符。']),
('review','多义词','The council will review the parking rules after the trial ends.','Which paraphrase preserves the meaning of “review” here?',['examine the rules again','publish a newspaper opinion','promise never to change the rules','sell copies of the rules'],0,['这里 review 是动词，表示重新审查规则。','review 可指评论，但本句是审查规则的动作。','审查并不意味着承诺永远不变。','review 不表示销售。']),
('record','多义词','The researcher will record the water level at noon every day.','What action is required?',['write down and keep the measurements','try to break a sporting record','remove the old measurement notes','guess tomorrow\'s water level'],0,['record 作动词，要求把测量值记下并保存。','体育纪录是 record 的另一名词用法，不符合这里。','记录不是删除。','记录已测值不是猜测未来数值。']),
('accurate','近义辨析','The old map placed the footbridge on the correct river bend. Its position was accurate.','What is supported by “accurate” in this context?',['the position matches the real location','the map contains many decorative details','the bridge is particularly narrow','the map was drawn recently'],0,['accurate 强调与实际位置相符。','细节丰富不保证准确。','桥宽和位置是否准确无关。','旧地图也可以准确，新旧不是本句判断标准。']),
('reliable','近义辨析','The alarm worked correctly in every weekly test, so the caretaker called it reliable.','Which conclusion best matches “reliable”?',['it can be depended on to work','it is the newest model available','it has an attractive design','it is difficult to understand'],0,['反复正常工作支撑“值得依赖”的含义。','可靠并不等于最新。','外观好看不是可靠性的证据。','难以理解和本句评价无关。']),
('sustainable','迁移理解','The farm replaced each harvested tree and kept the soil healthy for future planting. Its methods were sustainable.','Why are the methods described this way?',['they allow production to continue without exhausting natural resources','they produce the largest possible harvest immediately','they remove the need for any future work','they depend on replacing the workers every week'],0,['补种并维护土壤，为持续生产保留资源，符合可持续。','追求眼前最大产量不是可持续的定义。','可持续仍需要长期维护。','更换工人与自然资源的持续利用没有此处关系。']),
('resource','迁移理解','A retired builder offered knowledge and spare tools to the housing project. The team called both a resource.','What do the knowledge and tools have in common here?',['both can be used to help the project','both must be sold before work starts','both are naturally occurring minerals','both are finished buildings'],0,['resource 可指可用的知识或物资，不限于自然矿产。','资源可以直接使用，不必先出售。','知识和工具都不是矿产。','两者不是竣工建筑。']),
('balance','多义词','The programme sought a balance between historical detail and an enjoyable story.','Which meaning of “balance” is intended?',['giving suitable attention to two different needs','the money remaining in a bank account','the act of standing without falling','a device for weighing an object'],0,['这里指兼顾两项需求的平衡。','账户余额是 balance 的其他用法。','身体站稳不是本句的抽象平衡。','秤是 balance 的名词义，但不适用此句。']),
('significant','近义辨析','The new crossing made a significant improvement for people walking to the clinic.','What does the sentence claim?',['the improvement was important enough to matter','a statistical test must have been carried out','every traffic problem has been solved','the improvement was too small to notice'],0,['普通语境 significant 指值得注意、重要的改善。','没有统计检验线索，不能自动理解成统计显著。','重要改善并不等于解决全部问题。','significant 与小到无法察觉相反。']),
('privacy','迁移理解','The survey reported totals for each neighbourhood but did not publish names or individual addresses. It protected privacy.','What was protected?',['people\'s personal information from unwanted disclosure','the public right to inspect every individual answer','the survey team\'s supply of stationery','the number of neighbourhoods in the report'],0,['不公开姓名与个人住址，保护的是个人信息隐私。','隐私保护不会赋予公众查看所有个人答案的权利。','文具供应不是隐私。','社区数量不是私人资料的含义。'])]
for word,kind,context,prompt,options,answer,explanations in items:
    q={'id':'q-'+word+'-special','version':'1','senseId':'s-'+word+('-deal' if word=='address' else '-main'),'word':word,'context':context,'prompt':prompt,'options':options,'answer':answer,'explanations':explanations,'contextId':'ctx-'+word+'-special','type':kind}
    content['questions'].append(q)
    for article in content['articles']:
        if any(t['senseId']==q['senseId'] for t in article['targets']):article['questionIds'].append(q['id'])
(p/'content.json').write_text(json.dumps(content,ensure_ascii=False,separators=(',',':')),encoding='utf8')
manifest=json.loads((p/'manifest.json').read_text(encoding='utf8'));manifest['coverage']['uniqueQuestions']=len(content['questions']);manifest['coverage']['questionTypes']=sorted(set(q['type'] for q in content['questions']))
(p/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,separators=(',',':')),encoding='utf8')
sample=content['articles'][0];(p/'sample-learning-bundle.json').write_text(json.dumps({'format':'ContextFlowLearningBundle','version':1,'articles':[sample],'questions':[q for q in content['questions'] if q['id'] in sample['questionIds']]},ensure_ascii=False,indent=2),encoding='utf8')
